/*
 * A379587  Array read by ascending antidiagonals: A(n, k) = (k^n - 1)^2/(k -
 *          1), with k >= 2.
 * https://oeis.org/A379587
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy, tabl
 * Formula:   not stated
 * Range:     u8 n <= 10, u16 n <= 28, u32 n <= 54, u64 n <= 54, u128 n <= 54,
 *            big any n
 * Helpers:   big_pow
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  OEIS A379587 – array A(n, k) = ((k^n)-1)^2/(k-1) read by ascending antidiagonals
 *  Sequence is generated by scanning the matrix A over (n, k) with k >= 2.
 *  For each diagonal s = n + (k-2) you list the elements in decreasing row index
 *  order (i = s down to 0).  The term a(n) is the value at position n in this
 *  traversal. */
#include <stdint.h>
#include "../utils/big_pow.h"

seq_t a(idx_t n)
{
    /* Determine diagonal index s such that C(s-1) <= n < C(s),
     * where C(s) = (s+1)(s+2)/2 is the cumulative term count up to diag s. */
    idx_t s = 0;
    while ( ((__uint128_t)(s + 1) * (s + 2)) / 2 <= n )
        ++s;

    /* Elements before this diagonal */
    idx_t prev = ( (__uint128_t)s * (s + 1) ) / 2;
    /* Offset inside the diagonal (0 .. s) with order i = s .. 0 */
    idx_t offset = n - prev;
    idx_t i = s - offset;          /* row index (power in k^i)              */
    idx_t k = s - i + 2;            /* column index (base) >= 2              */

    /* Compute ((k^i)-1)^2 / (k-1) using big_pow for safety */
    seq_t base = (seq_t)k;
    seq_t exp  = (seq_t)i;

    seq_t pow_val = big_pow(base, exp);   /* base^i  */
    seq_t one      = (seq_t)1;
    seq_t val_minus = pow_val - one;      /* k^i - 1 */
    seq_t sq = val_minus * val_minus;     /* (k^i - 1)^2 */
    seq_t denom = base - one;             /* k - 1     */

    return sq / denom;                     /* integer division is exact        */
}
